sections.body:
先把一个能跑的程序摆出来，再回头解释它。新建一个文件叫 `hello.c`，写进去这五行：

```c
#include <stdio.h>

int main(void) {
    printf("你好，C 语言\n");
    return 0;
}
```

在这个平台上点运行就能看到结果。屏幕上出现一行字：

```
你好，C 语言
```

这就是一个完整的 C 程序。它做的事只有一件，往屏幕上打一行字。接下来几节把这五行拆开讲。

字符串里有些字符没法直接敲，要用反斜杠开头的写法表示。

```c
#include <stdio.h>

int main(void) {
    printf("第一行\n第二行\n");
    printf("姓名\t班级\t分数\n");
    printf("李雷\t三班\t92\n");
    printf("路径是 C:\\code\\hello.c\n");
    printf("双引号这么打 \"你好\"\n");
    printf("百分号这么打 100%%\n");
    return 0;
}
```

常用的就这几个：

| 写法 | 表示 |
|---|---|
| `\n` | 换行 |
| `\t` | 制表符，用来对齐列 |
| `\\` | 一个反斜杠 |
| `\"` | 一个双引号 |
| `%%` | 一个百分号，只在 `printf` 的格式串里需要 |

反斜杠在字符串里有特殊含义，所以想打一个真正的反斜杠必须写两个。Windows 路径里全是反斜杠，这个坑很容易踩。

这一章的目标是这个程序：给三科成绩，算出总分和平均分，打印成一张成绩单。

```c
#include <stdio.h>

int main(void) {
    char name[] = "李雷";
    int chinese = 88;
    int math = 95;
    int english = 79;

    int total = chinese + math + english;
    double average = total / 3.0;

    printf("姓名：%s\n", name);
    printf("语文 %d，数学 %d，英语 %d\n", chinese, math, english);
    printf("总分：%d\n", total);
    printf("平均分：%.1f\n", average);
    return 0;
}
```

运行结果：

```
姓名：李雷
语文 88，数学 95，英语 79
总分：262
平均分：87.3
```

这段代码里有三处值得停下来看：变量前面为什么要写 `int` 和 `double`，为什么平均分要除以 `3.0` 而不是 `3`，`printf` 里的 `%d` 和 `%.1f` 是什么。下面逐个讲。

::core:: C 里的每个==变量==都必须先说清楚存什么类型的数据，才能使用。这是它和 Python 最明显的区别。

```c
int chinese = 88;
double average = 87.3;
char grade = 'A';
```

写法是类型在前，名字在后，可以顺手给个初始值。也可以先声明再赋值：

```c
int total;
total = 88 + 95 + 79;
```

**声明了不赋值就直接用，值是随机的**。下面这句打出来的数字每次可能都不一样：

```c
int x;
printf("%d\n", x);
```

gcc 会警告 `'x' is used uninitialized`。养成习惯，声明的时候就给个初值。

变量名只能用字母、数字和下划线，不能用数字开头，也不能和 `int`、`return` 这类关键字重名。名字要能看懂，`total` 比 `t` 好。

把成绩单里写死的分数换成从键盘输入，用 `scanf`。

```c
#include <stdio.h>

int main(void) {
    int chinese, math, english;

    printf("依次输入语文、数学、英语成绩：");
    if (scanf("%d %d %d", &chinese, &math, &english) != 3) {
        printf("输入格式不对\n");
        return 1;
    }

    int total = chinese + math + english;
    printf("总分 %d，平均 %.1f\n", total, total / 3.0);
    return 0;
}
```

`scanf` 和 `printf` 长得像，但有两个地方不一样。

第一，**变量前面要加 `&`**。`&chinese` 的意思是 chinese 这个变量的地址。`scanf` 要往变量里写东西，光有值不行，得知道往哪写。这是第 5 章指针的内容，现在先记住读 `int`、`double`、`char` 都要加 `&`。忘了加 `&` 程序多半会直接崩掉。

第二，**读 `double` 要用 `%lf` 而不是 `%f`**。`printf` 里两个都行，`scanf` 里必须用 `%lf`。

```c
double price;
scanf("%lf", &price);
```

`scanf` 的返回值是成功读到了几个数据。上面判断它是不是等于 3，就能挡住用户乱敲字母的情况。养成检查返回值的习惯，程序会稳很多。

这一章的目标是这个程序：电脑心里有个数，你猜，它告诉你大了还是小了，直到猜中。

```c
#include <stdio.h>

int main(void) {
    int secret = 42;
    int guess = 0;
    int times = 0;

    printf("猜一个 1 到 100 的整数\n");
    while (guess != secret) {
        if (scanf("%d", &guess) != 1) {
            printf("读不到数字，退出\n");
            return 1;
        }
        times++;
        if (guess > secret) {
            printf("大了\n");
        } else if (guess < secret) {
            printf("小了\n");
        } else {
            printf("对了，用了 %d 次\n", times);
        }
    }
    return 0;
}
```

依次输入 50、25、37、42，输出是：

```
猜一个 1 到 100 的整数
大了
小了
小了
对了，用了 4 次
```

这个程序用到了两样新东西。`if` 让程序根据条件走不同的路，`while` 让一段代码反复执行。下面把它们讲清楚。

答案写死成 42 是为了每次结果一样，方便对照。想让它每局都不同，用随机数：

```c
#include <stdlib.h>
#include <time.h>

srand((unsigned)time(NULL));
int secret = rand() % 100 + 1;
```

`srand` 用当前时间做种子，`rand` 取出的余数落在 0 到 99，加 1 就变成 1 到 100。`srand` 整个程序只调一次，放在 `main` 开头。

`if` 后面的条件成立就执行大括号里的语句，不成立就跳过。

```c
int score = 88;

if (score >= 60) {
    printf("及格\n");
} else {
    printf("不及格\n");
}
```

要分成三档以上，用 `else if` 接下去：

```c
if (score >= 90) {
    printf("优秀\n");
} else if (score >= 80) {
    printf("良好\n");
} else if (score >= 60) {
    printf("及格\n");
} else {
    printf("不及格\n");
}
```

::core:: **从上往下第一个成立的分支执行完就结束，后面的一律跳过**。所以顺序很重要。上面这段如果把 60 分那一条放最前面，88 分会被判成及格，因为它先撞上了这一条。

大括号在只有一条语句时可以省略，但建议永远写上。下面这段的缩进骗了人，第二行不管条件成不成立都会执行：

```c
if (score >= 60)
    printf("及格\n");
    printf("发证书\n");    /* 这行和 if 无关 */
```

次数已知的重复用 `for`。

```c
for (int i = 1; i <= 5; i++) {
    printf("第 %d 次\n", i);
}
```

括号里三段用分号隔开，各管一件事：

- `int i = 1` 只在开始时执行一次，用来准备计数器。
- `i <= 5` 每轮开始前检查一次，成立才进循环体。
- `i++` 每轮结束后执行一次，等价于 `i = i + 1`。

上面这段打出五行。把条件改成 `i < 5` 就只有四行。边界差一个是很常见的错误，写完循环先想想到底跑几轮。

循环可以==嵌套==。下面打一张三角形的乘法表：

```c
#include <stdio.h>

int main(void) {
    for (int i = 1; i <= 3; i++) {
        for (int j = 1; j <= i; j++) {
            printf("%d*%d=%d\t", j, i, i * j);
        }
        printf("\n");
    }
    return 0;
}
```

::core:: 外层每转一圈，内层完整跑一遍。内层的上界是 `i`，所以每行的列数逐行增加，形成一个三角。

`i` 声明在 `for` 的括号里，出了循环就不存在了。想在循环外用它，得在外面声明。

次数不确定、靠条件停的重复用 `while`。

```c
int n = 1;
while (n < 100) {
    n = n * 2;
}
printf("%d\n", n);    /* 打出 128 */
```

`while` 先判断条件再执行，条件一开始就不成立的话，循环体一次都不跑。猜数字游戏用 `while` 正合适，因为不知道玩家要猜几次。

**写 `while` 一定要确认循环体里有东西能让条件变假**，否则就是==死循环==。下面这段永远停不下来，因为 n 一直没变：

```c
int n = 1;
while (n < 100) {
    printf("%d\n", n);
}
```

还有一个 `do while`，它先执行一次再判断条件，所以循环体至少跑一次：

```c
int guess;
do {
    printf("请输入 1 到 100 的数：");
    scanf("%d", &guess);
} while (guess < 1 || guess > 100);
```

这个写法适合先做一次再检查的场合，比如反复要求用户输入直到合法为止。注意 `do while` 末尾有分号。

::core:: `break` 立刻跳出整个循环，`continue` 跳过本轮剩下的语句直接进入下一轮。

```c
for (int i = 1; i <= 10; i++) {
    if (i == 5) {
        break;
    }
    printf("%d ", i);
}
/* 打出 1 2 3 4 */
```

```c
for (int i = 1; i <= 10; i++) {
    if (i % 2 == 0) {
        continue;
    }
    printf("%d ", i);
}
/* 打出 1 3 5 7 9 */
```

`break` 常用来提前结束搜索，找到了就没必要接着找：

```c
int nums[6] = {4, 9, 16, 25, 36, 49};
int target = 25;
int found = -1;

for (int i = 0; i < 6; i++) {
    if (nums[i] == target) {
        found = i;
        break;
    }
}
printf("在下标 %d\n", found);
```

要注意的是，**`break` 只跳出最里面那一层循环**。嵌套循环里想一次跳出两层，要么用一个==标志变量==，要么把内层拆成一个函数用 `return` 出来。

一个变量要和很多个固定值比较时，`switch` 比一长串 `else if` 清楚。

```c
#include <stdio.h>

int main(void) {
    int day = 3;

    switch (day) {
        case 1:
        case 2:
        case 3:
        case 4:
        case 5:
            printf("工作日\n");
            break;
        case 6:
        case 7:
            printf("周末\n");
            break;
        default:
            printf("这不是有效的星期\n");
    }
    return 0;
}
```

规则有三条要记：

- `case` 后面只能跟常量，不能写条件表达式。
- **执行完一个 `case` 不会自动停，会一直往下执行到遇见 `break`**。上面 1 到 5 共用一段代码就是利用了这个特性。忘写 `break` 是很常见的 bug。
- `default` 接住所有没匹配上的情况，放在最后，可以不写但建议写。

`switch` 也能用在 `char` 上，因为字符本质是整数：

```c
switch (grade) {
    case 'A': printf("优秀\n"); break;
    case 'B': printf("良好\n"); break;
    default:  printf("其他\n");
}
```

上一章的游戏所有代码都堆在 `main` 里。这一章把它拆成三个函数，每个函数只管一件事。

```c
#include <stdio.h>

int ask_guess(void);
int judge(int guess, int secret);
void report(int times);

int ask_guess(void) {
    int g = 0;
    printf("请输入你猜的数：");
    if (scanf("%d", &g) != 1) {
        return -1;
    }
    return g;
}

int judge(int guess, int secret) {
    if (guess > secret) {
        return 1;
    }
    if (guess < secret) {
        return -1;
    }
    return 0;
}

void report(int times) {
    printf("猜对了，一共用了 %d 次\n", times);
}

int main(void) {
    int secret = 42;
    int times = 0;

    while (1) {
        int g = ask_guess();
        if (g < 0) {
            printf("输入结束\n");
            return 1;
        }
        times++;

        int r = judge(g, secret);
        if (r > 0) {
            printf("大了\n");
        } else if (r < 0) {
            printf("小了\n");
        } else {
            report(times);
            break;
        }
    }
    return 0;
}
```

行数比原来多，但读起来更清楚。`main` 现在只剩流程，具体怎么读输入、怎么比较、怎么报告，各自关在自己的函数里。想改提示语只用动 `report`，想加输入范围校验只用动 `ask_guess`，不用在一大坨代码里翻。

下面把函数的写法讲清楚。

::core:: C 从上往下读代码，用到一个函数时它必须已经出现过。下面这段就违反了这条规矩：

```c
#include <stdio.h>

int main(void) {
    printf("%d\n", add(3, 5));   /* 此时编译器还不认识 add */
    return 0;
}

int add(int a, int b) {
    return a + b;
}
```

gcc 会警告 `implicit declaration of function 'add'`，然后按老规矩假设 `add` 返回 `int`。这次碰巧猜对了，程序还能跑出 8。要是 `add` 返回的是 `double`，结果就完全错了，而且不会有任何提示。C23 标准已经把这件事定成错误，所以见到这条警告必须处理。

有两种改法。

第一种，把 `add` 整个挪到 `main` 前面。函数少的时候够用，但函数一多顺序就难排，因为可能互相调用。

第二种，在文件开头写一行==函数原型==，只声明不写函数体：

```c
int add(int a, int b);
```

原型就是函数头加一个分号。它告诉编译器有这么个函数、参数和返回值是什么样，函数体可以放在文件任何地方。3.1 节那个程序开头的三行就是原型。

**推荐一律用原型**：所有原型集中放在文件顶部，读代码的人一眼就能看到这个文件提供哪些功能。原型里参数名可以省略，写 `int add(int, int);` 也行，但带上名字更好读。

调用函数时，实参的值被复制一份给==形参==。函数里改形参，外面的变量纹丝不动。

```c
#include <stdio.h>

void try_change(int x) {
    x = 100;
    printf("函数里 x = %d\n", x);
}

int main(void) {
    int a = 5;
    try_change(a);
    printf("函数外 a = %d\n", a);
    return 0;
}
```

输出是：

```
函数里 x = 100
函数外 a = 5
```

::core:: `a` 还是 5。因为传进去的是 `a` 的一份复制品，函数改的是复制品。这套规则叫==值传递==，C 的普通参数一律如此。

这带来一个限制：**光靠参数没法把结果带回来**。想让函数改动调用方的变量，得把变量的地址传进去，这是第 5 章指针要解决的问题。在那之前，函数结果都靠返回值带出来。

值传递也有好处。函数拿到的是自己的副本，随便改都不会影响外面，写起来不用担心副作用。

::core:: `return` 把结果送回调用处，同时立刻结束这个函数。

```c
int max_of(int a, int b) {
    if (a > b) {
        return a;
    }
    return b;
}
```

第一个 `return` 执行了，后面的语句就不会跑，所以这里不需要 `else`。用这个特点可以提前退出，让代码扁平：

```c
int safe_div(int a, int b) {
    if (b == 0) {
        return 0;      /* 除数为零，直接返回 */
    }
    return a / b;
}
```

**返回类型和 `return` 后面的值必须对得上**。声明成 `int` 却返回 `double`，小数部分会被砍掉。声明成 `int` 却有一条路径没写 `return`，gcc 会警告 `control reaches end of non-void function`，这种函数返回的是垃圾值。

不需要返回任何东西的函数，返回类型写 `void`：

```c
void print_line(void) {
    printf("--------------------\n");
}
```

`void` 函数里可以写一个光秃秃的 `return;` 提前结束，但不能 `return` 一个值。

一个函数只能返回一个值。想同时带回最大值和最小值，要么调用两次，要么用第 5 章的指针参数。

::core:: 函数里声明的变量只在这个函数里存在，出了大括号就没了。这叫==局部变量==。

```c
void f(void) {
    int n = 10;
}

void g(void) {
    printf("%d\n", n);    /* 错，g 看不见 f 里的 n */
}
```

不同函数里可以有同名变量，它们互不相干：

```c
#include <stdio.h>

void f(void) {
    int n = 1;
    printf("f 里 n = %d\n", n);
}

int main(void) {
    int n = 99;
    f();
    printf("main 里 n = %d\n", n);   /* 还是 99 */
    return 0;
}
```

==作用域==甚至细到大括号这一层。下面的 `t` 出了 `if` 就不存在：

```c
if (a > b) {
    int t = a;
    a = b;
    b = t;
}
printf("%d\n", t);    /* 错，t 已经不在了 */
```

写在所有函数外面的变量叫==全局变量==，所有函数都能读写它。全局变量能用，但**尽量不用**，因为任何一个函数都可能悄悄改掉它，出了问题很难查是谁改的。需要共享数据时，优先用参数传进去、用返回值带出来。

前面处理的都是几个孤零零的变量。一个班有几十个学生，总不能声明几十个变量。这一章用数组把它们装在一起。

```c
#include <stdio.h>

int main(void) {
    int score[8] = {88, 95, 79, 62, 100, 45, 73, 86};
    int n = 8;

    int sum = 0;
    int max = score[0];
    int min = score[0];
    int pass = 0;

    for (int i = 0; i < n; i++) {
        sum += score[i];
        if (score[i] > max) {
            max = score[i];
        }
        if (score[i] < min) {
            min = score[i];
        }
        if (score[i] >= 60) {
            pass++;
        }
    }

    printf("人数 %d\n", n);
    printf("平均 %.1f\n", (double)sum / n);
    printf("最高 %d，最低 %d\n", max, min);
    printf("及格 %d 人，及格率 %.1f%%\n", pass, 100.0 * pass / n);
    return 0;
}
```

运行结果：

```
人数 8
平均 78.5
最高 100，最低 45
及格 7 人，及格率 87.5%
```

一次循环把总分、最高、最低、及格人数全算出来了。要注意最高最低的初值取的是第一个元素，不是 0，否则全是负数的数据会算错。下面把数组讲清楚。

遍历用 `for`，下标从 0 走到长度减 1。

```c
int score[5] = {88, 95, 79, 62, 100};
for (int i = 0; i < 5; i++) {
    printf("第 %d 个是 %d\n", i + 1, score[i]);
}
```

条件写 `i < 5` 而不是 `i <= 5`。写成小于等于就会访问 `score[5]`，那个格子不属于这个数组。

在数组声明所在的函数里，可以用一个技巧算出元素个数：

```c
int score[8] = {88, 95, 79, 62, 100, 45, 73, 86};
int n = sizeof(score) / sizeof(score[0]);   /* n 是 8 */
```

`sizeof` 给出占用的字节数。整个数组的字节数除以单个元素的字节数就是元素个数。

::core:: **这个技巧只在数组声明的那个函数里有效**。把数组传给函数以后，函数拿到的只是一个地址，`sizeof` 算出来是地址的大小而不是整个数组的大小。所以 C 的规矩是：**传数组给函数时，必须把长度作为另一个参数一起传**。

```c
double average(int a[], int n) {
    int sum = 0;
    for (int i = 0; i < n; i++) {
        sum += a[i];
    }
    return (double)sum / n;
}
```

调用时写数组名就行，不加方括号：

```c
printf("%.1f\n", average(score, 8));
```

::core:: C 没有专门的==字符串==类型，字符串就是一个 `char` 数组，末尾放一个值为 0 的字符表示到此为止。这个结束标记写作 `\0`。

```c
char s[] = "abc";
```

这个数组实际占 4 个格子：`a`、`b`、`c`、`\0`。所以**声明字符数组时要留出==结束符==的位置**，想存 20 个字符就要写 `char name[21];`。

用 `%s` 打印，`printf` 从头一直打到遇见 `\0`：

```c
char name[20] = "李雷";
printf("你好，%s\n", name);
```

结束符要是被弄丢了，打印就会一路冲出数组边界，打出一堆乱码。下面这种写法就有这个毛病：

```c
char bad[3] = {'a', 'b', 'c'};   /* 没地方放 \0 */
printf("%s\n", bad);             /* 危险 */
```

可以逐个字符地处理字符串，因为它本来就是数组：

```c
#include <stdio.h>

int main(void) {
    char s[] = "hello";
    for (int i = 0; s[i] != '\0'; i++) {
        printf("%c-", s[i]);
    }
    printf("\n");
    return 0;
}
```

循环条件是当前字符不是结束符，这是最常见的遍历字符串的写法。

处理字符串的函数在 `<string.h>` 里，判断字符类别的在 `<ctype.h>` 里。

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char a[40] = "hello";
    char b[] = "world";

    printf("长度 %zu\n", strlen(a));       /* 5，不含结束符 */
    strcat(a, " ");
    strcat(a, b);
    printf("拼接后 %s\n", a);              /* hello world */

    char c[40];
    strcpy(c, a);
    printf("复制得到 %s\n", c);

    printf("比较 %d\n", strcmp("abc", "abd"));   /* 负数，前者小 */
    printf("相等吗 %d\n", strcmp("abc", "abc") == 0);

    printf("h 是字母吗 %d\n", isalpha('h') != 0);
    printf("7 是数字吗 %d\n", isdigit('7') != 0);
    printf("转大写 %c\n", toupper('h'));
    return 0;
}
```

`isalpha` 和 `isdigit` 成立时返回的是某个非 0 的数，不一定是 1，所以上面加了 `!= 0` 把它变成 1 或 0 再打印。写在 `if` 的条件里则不用管，非 0 就是真。

几个要点：

| 函数 | 作用 | 注意 |
|---|---|---|
| `strlen` | 字符串长度 | 不算结束符，返回值用 `%zu` 打印 |
| `strcpy` | 复制字符串 | 目标数组必须够大，否则越界 |
| `strcat` | 把后一个接到前一个末尾 | 同样要保证目标够大 |
| `strcmp` | 比较两个字符串 | 相等返回 0，**不能用 `==` 比较字符串** |

最后一条要特别记住。`a == b` 比的是两个数组的地址，不是内容，永远不会相等。判断内容一样必须写 `strcmp(a, b) == 0`。

`strcpy` 和 `strcat` 都不检查目标数组够不够大，是==缓冲区溢出==的常见来源。写的时候自己先算一遍长度。

`scanf("%s", ...)` 读字符串有两个毛病：遇到空格就停，而且不限制长度，输入过长会直接冲垮数组。读一行文字用 `fgets`。

```c
#include <stdio.h>
#include <string.h>

int main(void) {
    char line[100];

    printf("请输入一句话：");
    if (fgets(line, sizeof(line), stdin) == NULL) {
        printf("没读到东西\n");
        return 1;
    }

    line[strcspn(line, "\n")] = '\0';   /* 去掉末尾的换行符 */
    printf("你输入了 %zu 个字符：%s\n", strlen(line), line);
    return 0;
}
```

`fgets` 的三个参数是目标数组、最多读多少字节、从哪读。第二个参数直接写 `sizeof(line)`，就永远不会越界。第三个 `stdin` 表示从键盘读。

`fgets` 会把用户按的回车也存进来，所以要手动去掉。`strcspn(line, "\n")` 给出第一个换行符的位置，把那个位置改成结束符就把换行删掉了。

还有一个坑：`scanf` 和 `fgets` 混着用时，`scanf` 会把回车留在缓冲区里，接下来的 `fgets` 会立刻读到一个空行。避免的办法是要么全程用 `fgets`，要么在 `scanf` 之后手动把这一行剩下的字符读干净。

这一章从一个具体问题开始：写一个函数，把调用方的两个变量对调。

先看不用指针的写法，它是错的：

```c
#include <stdio.h>

void swap_wrong(int a, int b) {
    int t = a;
    a = b;
    b = t;
}

int main(void) {
    int x = 3, y = 8;
    swap_wrong(x, y);
    printf("x=%d y=%d\n", x, y);   /* 还是 x=3 y=8 */
    return 0;
}
```

第 3 章讲过，参数是复制进去的，函数换的是两个副本，外面的 x 和 y 根本没动。

改成传地址就对了：

```c
#include <stdio.h>

void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}

int main(void) {
    int x = 3, y = 8;
    printf("交换前 x=%d y=%d\n", x, y);
    swap(&x, &y);
    printf("交换后 x=%d y=%d\n", x, y);
    return 0;
}
```

输出是：

```
交换前 x=3 y=8
交换后 x=8 y=3
```

这段代码里有三个新符号：参数类型里的 `int *`、调用时的 `&x`、函数体里的 `*a`。下面逐个讲。

::core:: 变量存在内存里，内存的每个字节都有编号，这个编号就是==地址==。`&` 取出一个变量的地址。

```c
#include <stdio.h>

int main(void) {
    int x = 3;
    double d = 1.5;

    printf("x 的值是 %d\n", x);
    printf("x 的地址是 %p\n", (void *)&x);
    printf("d 的地址是 %p\n", (void *)&d);
    printf("x 占 %zu 字节\n", sizeof(x));
    return 0;
}
```

地址打出来是一串十六进制数，每次运行都不一样，这很正常。用 `%p` 打印地址，前面加 `(void *)` 是为了让类型和 `%p` 对上，不加会有警告。

第 1 章说 `scanf` 的变量前面要加 `&`，现在能解释了：`scanf` 要往变量里写数据，光知道变量当前的值没用，得知道它住在哪儿。所以传地址进去。

而 `printf` 只是读取值打出来，所以不用加 `&`。这就是两者写法不同的原因。

回头看开头那个 `swap`。

```c
void swap(int *a, int *b) {
    int t = *a;
    *a = *b;
    *b = t;
}
```

::core:: 调用时写 `swap(&x, &y)`，传进去的是 x 和 y 的地址。参数依然是值传递，函数拿到的是地址的副本。但地址的副本和原地址指向的是同一块内存，所以 `*a = *b` 改的就是外面的 x。

一句话概括：**值传递改不了外面的变量，传地址就能改**。

这个模式在 C 里到处都是。凡是函数需要修改调用方的数据，参数就写成指针。`scanf` 是这样，交换是这样，下一节的多返回值也是这样。

有一个细节要注意。函数里千万别写成这样：

```c
void swap_bad(int *a, int *b) {
    int *t = a;
    a = b;
    b = t;         /* 只换了两个指针的副本，外面的变量没动 */
}
```

这段换的是 a 和 b 这两个指针变量本身，而它们是副本。要改的是它们指向的内容，所以必须带星号。

数组和指针的关系很紧：**==数组名==在大多数场合会自动变成指向首元素的地址**。

```c
#include <stdio.h>

int main(void) {
    int a[5] = {10, 20, 30, 40, 50};
    int *p = a;          /* 不用写 &a[0]，数组名本身就是地址 */

    printf("%d\n", *p);       /* 10，第一个元素 */
    printf("%d\n", *(p + 2)); /* 30，往后数两个 */
    printf("%d\n", p[2]);     /* 30，和上面完全等价 */
    printf("%d\n", a[2]);     /* 30 */

    for (int i = 0; i < 5; i++) {
        printf("%d ", *(a + i));
    }
    printf("\n");
    return 0;
}
```

::core:: `p + 1` 不是地址加 1 个字节，而是往后挪一个元素。`int` 占 4 字节，所以 `p + 1` 的地址比 p 大 4。指针类型决定了这一步跨多远，这就是指针要分类型的原因。

由此得到一条等式：**`a[i]` 就是 `*(a + i)` 的另一种写法**，两者完全一样。

反过来，两个指向同一个数组的指针相减，得到的是它们之间隔了几个元素：

```c
int a[5] = {10, 20, 30, 40, 50};
printf("%ld\n", (long)(&a[3] - a));   /* 打出 3 */
```

这也解释了第 4 章的说法：数组传给函数会==退化==成指针。函数收到的其实是 `int *`，所以 `sizeof` 在函数里算不出数组长度，必须另外传长度。下面这两种写法在函数参数里是一回事：

```c
double average(int a[], int n);
double average(int *a, int n);
```

函数只能 `return` 一个值。想同时带回好几个结果，就把存放结果的变量地址传进去，让函数往里写。

```c
#include <stdio.h>

void min_max(const int *a, int n, int *out_min, int *out_max) {
    int mn = a[0];
    int mx = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < mn) {
            mn = a[i];
        }
        if (a[i] > mx) {
            mx = a[i];
        }
    }
    *out_min = mn;
    *out_max = mx;
}

int main(void) {
    int a[6] = {17, 4, 92, 38, 55, 71};
    int lo = 0, hi = 0;

    min_max(a, 6, &lo, &hi);
    printf("最小 %d，最大 %d\n", lo, hi);
    return 0;
}
```

输出是 `最小 4，最大 92`。

第一个参数写成 `const int *a`，`const` 表示这个函数只读不写这块数据。加上它有两个好处：读代码的人一眼知道数组不会被改，写错了编译器还会拦住。**只读的指针参数都加 `const`，这是好习惯**。

按惯例，用来输出结果的参数名字带上 `out_` 之类的前缀，调用的人一看就知道哪些参数是往里写的。

指针出错的后果比普通变量严重，因为它直接操作内存。有两种情况要防。

**第一种，指针没初始化就用。**

```c
int *p;        /* p 里是随机地址 */
*p = 10;       /* 往一个不知道哪儿的地方写，程序多半崩掉 */
```

崩掉时的报错是 Segmentation fault，意思是访问了不该访问的内存。声明指针时如果还不知道指向哪，就先赋成 `NULL`：

```c
int *p = NULL;
```

`NULL` 是一个特殊的地址值，表示这个指针目前不指向任何东西。

**第二种，用之前不检查是不是空。**

```c
void print_all(const int *a, int n) {
    if (a == NULL) {
        printf("没有数据\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        printf("%d ", a[i]);
    }
    printf("\n");
}
```

函数收到指针参数，先判一下是不是 `NULL` 再用，能挡掉一大类崩溃。

还有一种情况：指针指向的变量已经消失了，比如函数返回了一个局部变量的地址。

```c
int *bad(void) {
    int x = 10;
    return &x;      /* 错，函数一结束 x 就没了 */
}
```

gcc 会警告 `function returns address of local variable`。要返回数据，要么返回值本身，要么让调用方先准备好空间再把地址传进来。

::core:: 一个联系人有姓名、电话、年龄三样东西。用三个平行数组分开存也能做，但改一条记录要同时改三个地方，一不小心就错位。==结构体==把它们捆成一个整体，一条记录就是一个变量。

先把下面这段跑起来。

```c
#include <stdio.h>
#include <string.h>

struct Contact {
    char name[20];
    char phone[16];
    int  age;
};

int main(void) {
    struct Contact book[3];

    strcpy(book[0].name, "张伟");
    strcpy(book[0].phone, "13800138000");
    book[0].age = 28;

    strcpy(book[1].name, "李娜");
    strcpy(book[1].phone, "13900139000");
    book[1].age = 34;

    strcpy(book[2].name, "王强");
    strcpy(book[2].phone, "13700137000");
    book[2].age = 22;

    printf("姓名 电话 年龄\n");
    for (int i = 0; i < 3; i++) {
        printf("%s %s %d\n", book[i].name, book[i].phone, book[i].age);
    }
    return 0;
}
```

编译运行的命令还是这一条：

```
gcc -std=c17 -O0 -Wall -Wextra -o prog prog.c -lm
./prog
```

屏幕上出来一张三行的表。关键在 `book[i]`：下标一变，姓名、电话、年龄三个字段一起跟着变，不会串行。下面把这里面的每一步拆开讲。

::core:: `struct Contact { ... };` 这句话只是定义了一个新类型，不产生变量，也不占内存。它告诉编译器：以后凡是叫 `struct Contact` 的东西，里面装着一个 20 字节的名字、一个 16 字节的电话和一个整数。

三件事要记住。

- 末尾的分号不能少。漏掉分号时编译器往往把错误报在下一行，看着莫名其妙，先回头检查上一个结构体定义。
- 类型名是两个词 `struct Contact`，不是 `Contact`。想写成一个词要先用 typedef，见 6.5。
- 定义通常放在所有函数外面，这样整个文件都能用。

==成员==在内存里挨着放，所以一条记录的大小大致等于各成员之和。自己量一下：

```c
#include <stdio.h>

struct Contact {
    char name[20];
    char phone[16];
    int  age;
};

int main(void) {
    struct Contact a;
    printf("一条记录 %zu 字节\n", sizeof a);
    printf("成员加起来 %zu 字节\n", sizeof a.name + sizeof a.phone + sizeof a.age);
    return 0;
}
```

这里两个数相等，都是 40。换一个成员顺序就不一定相等了，编译器为了让 int 落在 4 的整数倍地址上，会在成员之间插几个空字节。所以算内存永远用 sizeof，不要自己把成员大小加起来。

结构体和普通类型一样能组成数组，一个数组就是一整本通讯录。定义时把每条记录各用一对花括号括起来：

```c
struct Contact book[3] = {
    {"张伟", "13800138000", 28},
    {"李娜", "13900139000", 34},
    {"王强", "13700137000", 22},
};
```

遍历就是普通的 for 循环，先取到第 i 条记录，再取它的成员。按姓名查找的完整程序：

```c
#include <stdio.h>
#include <string.h>

struct Contact {
    char name[20];
    char phone[16];
    int  age;
};

int find(struct Contact book[], int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(book[i].name, name) == 0) return i;
    }
    return -1;
}

int main(void) {
    struct Contact book[3] = {
        {"张伟", "13800138000", 28},
        {"李娜", "13900139000", 34},
        {"王强", "13700137000", 22},
    };

    int k = find(book, 3, "李娜");
    if (k >= 0) {
        printf("找到了，%s 的电话是 %s\n", book[k].name, book[k].phone);
    } else {
        printf("没找到\n");
    }
    return 0;
}
```

两个细节。第一，找不到时返回 -1，调用方必须先判一下再用，直接拿 -1 当下标就越界了。第二，数组作参数传的是首地址，函数里不知道有多少条，所以必须额外传一个 n 进去。

每次都写 `struct Contact` 太啰嗦。==typedef== 给类型起个别名，之后写一个词就行：

```c
typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

Contact a;
Contact book[100];
```

本课程后面都用这种写法。

有一个例外：结构体里要放指向自己的指针时，必须保留标签名，因为花括号还没结束，别名 Contact 还不存在。

```c
typedef struct Node {
    int value;
    struct Node *next;
} Node;
```

链表就是这么串起来的，第七章会用到。

::core:: typedef 只是换个名字，不改变任何行为。`Contact` 和 `struct Contact` 在编译器眼里完全一样。

::core:: 把结构体传进函数，传进去的是一份复制品，函数里怎么改都影响不到原件。想改原件就传指针。

```c
#include <stdio.h>

typedef struct {
    char name[20];
    int  age;
} Contact;

void birthday_copy(Contact c) { c.age++; }
void birthday_real(Contact *c) { c->age++; }

int main(void) {
    Contact a = {"张伟", 28};

    birthday_copy(a);
    printf("传值之后 %d\n", a.age);

    birthday_real(&a);
    printf("传指针之后 %d\n", a.age);
    return 0;
}
```

输出是 28 和 29。第一次调用改的是副本，函数一返回副本就没了。

通过指针访问成员用==箭头==，`c->age` 是 `(*c).age` 的简写。两种都对，箭头更常用。

除了能改原件，传指针还省时间。一条记录 40 字节，每次调用都复制一遍并不划算，记录再大一些差别更明显。所以工程里的习惯是结构体一律传指针，只读的加上 ==const==：

```c
void print_contact(const Contact *c) {
    printf("%s %d\n", c->name, c->age);
}
```

加了 const，函数里再想改成员编译器会直接报错，等于给自己上了一道保险。

::core:: 上一章的 `Contact book[3]` 写死了只能放三条。想放一百条就得改代码重编译，放少了浪费，放多了不够用。==动态内存==让程序在运行时决定要多大空间。

下面这段先要 2 条的空间，装满了就翻倍，最后装下 5 条。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

int main(void) {
    int cap = 2, n = 0;
    Contact *book = malloc(cap * sizeof *book);
    if (book == NULL) {
        printf("内存不够\n");
        return 1;
    }

    const char *names[] = {"张伟", "李娜", "王强", "赵敏", "陈杰"};
    for (int i = 0; i < 5; i++) {
        if (n == cap) {
            cap *= 2;
            Contact *bigger = realloc(book, cap * sizeof *book);
            if (bigger == NULL) { free(book); return 1; }
            book = bigger;
            printf("扩容到 %d 条\n", cap);
        }
        strcpy(book[n].name, names[i]);
        strcpy(book[n].phone, "13800138000");
        book[n].age = 20 + i;
        n++;
    }

    for (int i = 0; i < n; i++) {
        printf("%s %d\n", book[i].name, book[i].age);
    }

    free(book);
    return 0;
}
```

输出里会看到两次扩容，从 2 到 4 再到 8，然后是五条记录。`book` 是一个指针，指向一块运行时申请来的内存，但用起来和数组一模一样，照样写 `book[i].name`。下面把 malloc、realloc、free 三件事分开说。

realloc 把已有的一块内存换成新大小，原来的数据会保留。

```c
Contact *bigger = realloc(book, cap * sizeof *book);
if (bigger == NULL) { free(book); return 1; }
book = bigger;
```

必须用一个新指针接返回值，不能写成 `book = realloc(book, ...)`。因为 realloc 失败时返回 NULL 而原来那块内存还在，如果直接赋给 book，原地址就丢了，那块内存再也 free 不掉。

::core:: realloc 可能把数据搬到别的地方，返回的地址和原来不一定相同。所以调用之后，所有指向老地址的指针全部作废，只能用返回的新地址。

扩容策略一般是翻倍，不是每次加一。翻倍的话，装 n 个元素总共只搬几次；每次加一的话每加一个都可能搬一次，数据量大了明显变慢。

realloc 还有两个特殊用法：第一个参数传 NULL 等于 malloc，新大小传 0 等于 free。知道就行，平时分开写更清楚。

动态内存最常出的两类事故，都是往边界外面写。

::core:: 第一类是==下标越界==。malloc 申请了 n 个元素，合法下标就是 0 到 n-1。写 `book[n]` 编译器不会报错，运行时也不一定崩，但你已经踩到了别人的内存上。C 不做边界检查，这件事只能靠自己守。

第二类是字符串少留一个字节。C 的字符串结尾必须有一个 `'\0'`，它也占一个字节。所以复制一个长度 5 的字符串，要申请 6 字节：

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    const char *src = "hello";
    char *dst = malloc(strlen(src) + 1);   // 加一是给 '\0' 留的
    if (dst == NULL) return 1;

    strcpy(dst, src);
    printf("%s 长度 %zu\n", dst, strlen(dst));

    free(dst);
    return 0;
}
```

漏掉这个加一，strcpy 会把结束符写到第 6 个字节，正好越界一个。这种错误特别阴险，多数时候程序照跑不误，直到某次那一个字节恰好覆盖了要紧的东西。

加 `-fsanitize=address` 编译能当场抓住这两类问题，写涉及指针的代码时值得顺手带上。

写完一段带 malloc 的代码，照着过一遍：

- malloc 的返回值检查 NULL 了吗
- 申请的字节数是个数乘 sizeof 吗，字符串有没有加一
- 每条返回路径上都 free 了吗，包括中途出错提前 return 的那条
- realloc 用新指针接了吗，失败时老指针 free 了吗
- free 之后还有没有代码用到这个指针
- 下标的范围是不是 0 到 n-1

第三条最容易漏。函数中间有好几个 `return -1`，很容易某一条忘了先 free。一个常用的写法是把出错处理集中到函数末尾：

```c
int work(void) {
    int *a = malloc(100 * sizeof *a);
    if (a == NULL) return -1;

    int rc = -1;
    if (/* 某个条件不满足 */ 0) goto done;
    if (/* 另一个条件不满足 */ 0) goto done;
    rc = 0;

done:
    free(a);
    return rc;
}
```

goto 在别处不建议用，但集中清理资源是它公认合适的场合，标准库和内核里到处都是这种写法。

::core:: 程序一退出，内存里的数据就没了。要让通讯录下次还在，得写到文件里。

下面这段先把三条记录写进 contacts.txt，再重新打开读回来。

```c
#include <stdio.h>

typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

int main(void) {
    Contact book[3] = {
        {"张伟", "13800138000", 28},
        {"李娜", "13900139000", 34},
        {"王强", "13700137000", 22},
    };

    FILE *fp = fopen("contacts.txt", "w");
    if (fp == NULL) {
        printf("打不开文件\n");
        return 1;
    }
    for (int i = 0; i < 3; i++) {
        fprintf(fp, "%s %s %d\n", book[i].name, book[i].phone, book[i].age);
    }
    fclose(fp);
    printf("已写入 3 条\n");

    Contact back[10];
    int n = 0;
    fp = fopen("contacts.txt", "r");
    if (fp == NULL) {
        printf("打不开文件\n");
        return 1;
    }
    while (n < 10 && fscanf(fp, "%19s %15s %d",
                            back[n].name, back[n].phone, &back[n].age) == 3) {
        n++;
    }
    fclose(fp);

    printf("读回 %d 条\n", n);
    for (int i = 0; i < n; i++) {
        printf("%s %s %d\n", back[i].name, back[i].phone, back[i].age);
    }
    return 0;
}
```

跑完当前目录会多出一个 contacts.txt，用文本编辑器能直接打开看。程序里的三步是固定套路：fopen 打开并检查，fprintf 或 fscanf 读写，fclose 关闭。下面逐个说。

这两个函数和 printf、scanf 长得一样，只是第一个参数换成了 `FILE *`。

```c
fprintf(fp, "%s %s %d\n", name, phone, age);
fscanf(fp, "%19s %15s %d", name, phone, &age);
```

写的时候格式随意，读的时候格式要能对上，否则读出来的是乱的。所以自己存自己读的文件，最好用固定分隔的简单格式，一行一条记录。

fscanf 的返回值是成功读到的项数。上面那句要读三项，返回 3 才算这一行完整读到了。用它当循环条件，读不满就自然停下：

```c
while (fscanf(fp, "%19s %15s %d", name, phone, &age) == 3) {
    // 处理这一条
}
```

`%19s` 里的 19 限制最多读 19 个字符，加上结束符正好填满 `char name[20]`。不写这个数字，遇到超长的输入就会写出数组之外，这是 C 里最经典的一类漏洞。scanf 家族的 `%s` 一定要带长度限制。

fscanf 的 `%s` 遇到空格就停。所以姓名里带空格的话，一个名字会被切成两半，后面全乱。这时要换成按行读。

fgets 一次读一整行，空格照单全收。

```c
char line[256];
while (fgets(line, sizeof line, fp) != NULL) {
    // line 里是一整行，末尾通常带着换行符
}
```

三个要点。

第一，第二个参数是缓冲区的总大小，包括结束符。写 `sizeof line` 就不会算错。fgets 最多读 size-1 个字符，一定会留位置放结束符，所以它不会越界，比 gets 安全。gets 已经被标准删掉，永远不要用。

第二，读到的内容末尾带着换行符。要去掉的话：

```c
line[strcspn(line, "\n")] = '\0';
```

strcspn 返回第一个换行符的位置，没有换行符就返回整行长度，两种情况这一句都对。

第三，如果一行超过缓冲区，fgets 只读前面一段，剩下的下次再读，末尾就不带换行符。行可能很长时要判断一下有没有读到换行符。

读进来的一整行再自己拆成字段，常用 sscanf，它和 fscanf 一样只是从字符串里读：

```c
int day, high, low;
if (sscanf(line, "%d,%d,%d", &day, &high, &low) == 3) {
    // 三项都读到了
}
```

先 fgets 再 sscanf 是处理文本文件最稳的组合：一行读坏了只影响这一行，不会把后面全带乱。

::core:: ==文本格式==人能看懂，但存浮点数会丢精度，解析也慢。==二进制格式==把结构体原样搬进文件，用 fwrite 和 fread。

```c
FILE *fp = fopen("book.dat", "wb");
fwrite(book, sizeof(Contact), 3, fp);   // 写 3 条，每条 sizeof(Contact) 字节
fclose(fp);

fp = fopen("book.dat", "rb");
int n = (int)fread(back, sizeof(Contact), 10, fp);   // 最多读 10 条，返回实际读到几条
fclose(fp);
```

两个函数的参数一样：数据地址、单条大小、条数、文件指针。返回值都是实际处理的条数，不是字节数。

好处是快，而且不用写解析代码。代价有三个：文件用记事本打开是乱码；换一台机器可能读不出来，因为整数的字节顺序和结构体的对齐方式可能不同；结构体一旦改了字段，老文件全部作废。

所以选哪种看用途。配置文件、日志、要给人看或者要跨机器传的数据用文本；程序自己临时存的大批数据用二进制。这门课后面都用文本，因为出问题时能直接打开文件看，好调试。

::core:: 通讯录写到现在已经好几百行，全挤在一个文件里，找函数要翻半天。按职责拆开：数据结构和函数声明放==头文件==，实现放一个源文件，主流程放另一个源文件。

contact.h 只写别人需要知道的东西：

```c
#ifndef CONTACT_H
#define CONTACT_H

typedef struct {
    char name[20];
    char phone[16];
    int  age;
} Contact;

int  contact_find(const Contact *book, int n, const char *name);
void contact_print(const Contact *c);

#endif
```

contact.c 写实现：

```c
#include <stdio.h>
#include <string.h>
#include "contact.h"

int contact_find(const Contact *book, int n, const char *name) {
    for (int i = 0; i < n; i++) {
        if (strcmp(book[i].name, name) == 0) return i;
    }
    return -1;
}

void contact_print(const Contact *c) {
    printf("%s %s %d\n", c->name, c->phone, c->age);
}
```

main.c 只管流程：

```c
#include <stdio.h>
#include "contact.h"

int main(void) {
    Contact book[2] = {
        {"张伟", "13800138000", 28},
        {"李娜", "13900139000", 34},
    };
    int k = contact_find(book, 2, "李娜");
    if (k >= 0) contact_print(&book[k]);
    return 0;
}
```

编译时把两个 .c 都交给 gcc：

```
gcc -std=c17 -O0 -Wall -Wextra -o prog main.c contact.c -lm
```

注意 .h 文件不出现在命令里。头文件不参与编译，它是被 include 进来的，等于把内容原样贴到那一行。

C 自带的库不大，但天天要用的就那么几个头文件。这一章用一个统计小工具把它们串起来。

先跑这段。

```c
#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(void) {
    char text[] = "The C language is small. The C standard library is not.";

    printf("总长度 %zu\n", strlen(text));

    int letters = 0, spaces = 0;
    for (int i = 0; text[i] != '\0'; i++) {
        if (isalpha((unsigned char)text[i])) letters++;
        else if (isspace((unsigned char)text[i])) spaces++;
    }
    printf("字母 %d 个 空格 %d 个\n", letters, spaces);

    char copy[128];
    snprintf(copy, sizeof copy, "%s", text);
    for (int i = 0; copy[i] != '\0'; i++) {
        copy[i] = (char)tolower((unsigned char)copy[i]);
    }

    int words = 0;
    char longest[32] = "";
    char *p = strtok(copy, " .,");
    while (p != NULL) {
        words++;
        if (strlen(p) > strlen(longest)) snprintf(longest, sizeof longest, "%s", p);
        p = strtok(NULL, " .,");
    }
    printf("单词 %d 个 最长的是 %s\n", words, longest);

    return 0;
}
```

三行输出，一共用到了 strlen、isalpha、isspace、tolower、strtok、snprintf 六个库函数。下面按头文件分类讲。

除了第七章的 malloc 和 free，这个头文件还有几组常用的东西。

字符串转数字：

```c
int   n = atoi("42");          // 转不了就返回 0，分不清是失败还是真的 0
long  m = strtol("42", NULL, 10);   // 更可靠，10 表示十进制
double d = atof("3.14");
```

要判断转换成不成功就用 strtol，它的第二个参数能告诉你停在了哪里：

```c
char *end;
long v = strtol(s, &end, 10);
if (end == s) {
    printf("这不是个数字\n");
}
```

排序用 qsort，它对任何类型都能排，代价是要自己写一个==比较函数==：

```c
int cmp_int(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x > y) - (x < y);
}

qsort(arr, n, sizeof arr[0], cmp_int);
```

::core:: 比较函数收两个 `const void *`，要先转成真实类型再解引用。返回负数表示第一个排前面，正数表示第二个排前面，0 表示相等。用 `(x > y) - (x < y)` 而不是 `x - y`，是因为两个很大的整数相减会溢出，结果符号可能反过来。

==随机数==用 rand，范围是 0 到 RAND_MAX。程序开头调一次 `srand(time(NULL))` 换种子，否则每次运行出的是同一串数。time 在 time.h 里。

另外 `abs` 求整数绝对值，`exit(0)` 直接结束程序，都在这里。

数学函数在 math.h，参数和返回值基本都是 double。

```c
sqrt(x)        // 平方根
pow(x, y)      // x 的 y 次方
fabs(x)        // 浮点数绝对值，整数用 abs
floor(x)       // 向下取整
ceil(x)        // 向上取整
round(x)       // 四舍五入
fmod(x, y)     // 浮点取余，整数的 % 不能用于 double
log(x)         // 自然对数
log10(x)       // 常用对数
sin cos tan    // 三角函数，参数是弧度
```

编译命令末尾的 `-lm` 就是为它准备的。==数学库==不在默认链接的库里，不加这个参数会报 undefined reference to sqrt。而且它必须写在源文件后面。

一个完整例子，算一组数的标准差：

```c
#include <stdio.h>
#include <math.h>

int main(void) {
    double a[5] = {2.0, 4.0, 4.0, 4.0, 6.0};
    int n = 5;

    double sum = 0.0;
    for (int i = 0; i < n; i++) sum += a[i];
    double mean = sum / n;

    double var = 0.0;
    for (int i = 0; i < n; i++) var += pow(a[i] - mean, 2);
    var /= n;

    printf("平均 %.2f 标准差 %.2f\n", mean, sqrt(var));
    return 0;
}
```

::core:: 浮点数还有一件事要留心：不要用等号比较两个 double。`0.1 + 0.2 == 0.3` 是假的，因为二进制存不下这些小数。正确做法是看差的绝对值够不够小：

```c
if (fabs(x - y) < 1e-9) { /* 认为相等 */ }
```

先想清楚存什么，再写代码。这一步花的时间最值。

一名学生：

```c
typedef struct {
    int    id;
    char   name[20];
    double chinese;
    double math;
    double english;
} Student;
```

三科分开存而不是用一个 `double score[3]`，是因为后面要按科目名输出，分开写更直白。要是科目数会变，就该用数组加一个科目名表。

平均分不存进结构体，用的时候算：

```c
double avg_of(const Student *s) {
    return (s->chinese + s->math + s->english) / 3.0;
}
```

::core:: 理由是任何能算出来的字段都不该存。存了就有两份真相，改了成绩忘了更新平均分，两边就对不上了。

一个班：

```c
typedef struct {
    Student *data;   // 堆上的数组
    int      n;      // 已经放了几个
    int      cap;    // 一共能放几个
} Roster;
```

把指针、个数、容量三样捆在一起，是==动态数组==的标准写法。以后所有函数只要收一个 `Roster *`，不用再传三个参数，也不会出现个数和数组对不上的情况。

==容器==的==生命周期==从初始化开始，到释放结束，中间是增删查改。

```c
void roster_init(Roster *r) {
    r->data = NULL;
    r->n = 0;
    r->cap = 0;
}

void roster_free(Roster *r) {
    free(r->data);
    r->data = NULL;
    r->n = 0;
    r->cap = 0;
}
```

初始时指针给 NULL，容量给 0。这样 roster_add 里不用特判第一次，因为 `realloc(NULL, size)` 等价于 malloc。

```c
int roster_add(Roster *r, Student s) {
    if (r->n == r->cap) {
        int cap = (r->cap == 0) ? 4 : r->cap * 2;
        Student *bigger = realloc(r->data, (size_t)cap * sizeof *bigger);
        if (bigger == NULL) return -1;
        r->data = bigger;
        r->cap = cap;
    }
    r->data[r->n++] = s;
    return 0;
}
```

返回 0 表示成功，-1 表示内存不够。调用方该判一下，虽然小程序里基本不会失败。

查找按学号，找不到返回 -1：

```c
int roster_find(const Roster *r, int id) {
    for (int i = 0; i < r->n; i++) {
        if (r->data[i].id == id) return i;
    }
    return -1;
}
```

::core:: 返回下标而不是返回指针，是因为下标在数组扩容后还有效，指针会失效。这一点在第七章说过，realloc 可能搬家。

排序直接用 qsort，自己写一个按平均分降序的比较函数。

```c
static int by_avg_desc(const void *a, const void *b) {
    double x = avg_of((const Student *)a);
    double y = avg_of((const Student *)b);
    return (y > x) - (y < x);
}

qsort(r.data, (size_t)r.n, sizeof r.data[0], by_avg_desc);
```

比较函数收到的两个指针直接指向 Student，因为数组元素本身就是 Student。降序就是把 x 和 y 的位置反过来写。

统计部分只是几个循环：

```c
double total = 0.0;
int best = 0, fail = 0;
for (int i = 0; i < r.n; i++) {
    total += avg_of(&r.data[i]);
    if (avg_of(&r.data[i]) > avg_of(&r.data[best])) best = i;
    if (r.data[i].chinese < 60 || r.data[i].math < 60 || r.data[i].english < 60) fail++;
}
printf("班级平均 %.2f\n", total / r.n);
```

`r.n` 为 0 时这里会除以零，实际程序要先判一下空。

::core:: 一个建议：统计和输出分开。统计函数只算数不打印，打印交给另一个函数。这样以后想把结果写进文件而不是屏幕，只改打印那一处。

格式选一行一条，字段用空格分开，姓名不含空格。

```c
int roster_save(const Roster *r, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) return -1;
    for (int i = 0; i < r->n; i++) {
        const Student *s = &r->data[i];
        fprintf(fp, "%d %s %.1f %.1f %.1f\n",
                s->id, s->name, s->chinese, s->math, s->english);
    }
    fclose(fp);
    return 0;
}

int roster_load(Roster *r, const char *path) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return -1;

    char line[128];
    while (fgets(line, sizeof line, fp) != NULL) {
        Student s;
        if (sscanf(line, "%d %19s %lf %lf %lf",
                   &s.id, s.name, &s.chinese, &s.math, &s.english) != 5) continue;
        if (roster_add(r, s) != 0) break;
    }
    fclose(fp);
    return 0;
}
```

三个要点。

第一，读用 fgets 加 sscanf，不直接用 fscanf。这样某一行格式坏了，`continue` 跳过它就行，不会把后面全带乱。

第二，`%19s` 的长度限制不能省，姓名数组是 20 字节。

第三，double 在 scanf 家族里的格式是 `%lf`，不是 `%f`。printf 里两个都行，scanf 里写错就读不进去，这是很常见的一个错。

存盘用 `"w"` 模式，每次覆盖。想追加就用 `"a"`，但那样容易存出重复记录，一般还是整份重写更省心。

把上面几段拼起来，加一段主流程。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int    id;
    char   name[20];
    double chinese;
    double math;
    double english;
} Student;

typedef struct {
    Student *data;
    int      n;
    int      cap;
} Roster;

static double avg_of(const Student *s) {
    return (s->chinese + s->math + s->english) / 3.0;
}

static void roster_init(Roster *r) {
    r->data = NULL; r->n = 0; r->cap = 0;
}

static void roster_free(Roster *r) {
    free(r->data);
    r->data = NULL; r->n = 0; r->cap = 0;
}

static int roster_add(Roster *r, Student s) {
    if (r->n == r->cap) {
        int cap = (r->cap == 0) ? 4 : r->cap * 2;
        Student *bigger = realloc(r->data, (size_t)cap * sizeof *bigger);
        if (bigger == NULL) return -1;
        r->data = bigger;
        r->cap = cap;
    }
    r->data[r->n++] = s;
    return 0;
}

static int roster_find(const Roster *r, int id) {
    for (int i = 0; i < r->n; i++) {
        if (r->data[i].id == id) return i;
    }
    return -1;
}

static int by_avg_desc(const void *a, const void *b) {
    double x = avg_of((const Student *)a);
    double y = avg_of((const Student *)b);
    return (y > x) - (y < x);
}

static int roster_save(const Roster *r, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) return -1;
    for (int i = 0; i < r->n; i++) {
        const Student *s = &r->data[i];
        fprintf(fp, "%d %s %.1f %.1f %.1f\n",
                s->id, s->name, s->chinese, s->math, s->english);
    }
    fclose(fp);
    return 0;
}

static int roster_load(Roster *r, const char *path) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return -1;
    char line[128];
    while (fgets(line, sizeof line, fp) != NULL) {
        Student s;
        if (sscanf(line, "%d %19s %lf %lf %lf",
                   &s.id, s.name, &s.chinese, &s.math, &s.english) != 5) continue;
        if (roster_add(r, s) != 0) break;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    Roster r;
    roster_init(&r);

    Student init[5] = {
        {1001, "张伟", 88.0, 92.5, 79.0},
        {1002, "李娜", 95.0, 88.0, 91.5},
        {1003, "王强", 72.5, 65.0, 58.0},
        {1004, "赵敏", 81.0, 79.5, 85.0},
        {1005, "陈杰", 59.0, 71.0, 66.5},
    };
    for (int i = 0; i < 5; i++) roster_add(&r, init[i]);
    printf("录入 %d 名学生\n", r.n);

    int k = roster_find(&r, 1003);
    if (k >= 0) printf("学号 1003 是 %s 平均 %.2f\n", r.data[k].name, avg_of(&r.data[k]));

    qsort(r.data, (size_t)r.n, sizeof r.data[0], by_avg_desc);
    printf("按平均分排名\n");
    for (int i = 0; i < r.n; i++) {
        printf("%d %s %.2f\n", i + 1, r.data[i].name, avg_of(&r.data[i]));
    }

    double total = 0.0;
    int fail = 0;
    for (int i = 0; i < r.n; i++) {
        total += avg_of(&r.data[i]);
        const Student *s = &r.data[i];
        if (s->chinese < 60 || s->math < 60 || s->english < 60) fail++;
    }
    printf("班级平均 %.2f\n", total / r.n);
    printf("有不及格科目的 %d 人\n", fail);

    roster_save(&r, "scores.txt");
    printf("已存入 scores.txt\n");

    Roster r2;
    roster_init(&r2);
    roster_load(&r2, "scores.txt");
    printf("读回 %d 条 第一条是 %s\n", r2.n, r2.data[0].name);

    roster_free(&r);
    roster_free(&r2);
    return 0;
}
```

