#include <stdio.h>

int remove_value(int *a, int n, int v);

int remove_value(int *a, int n, int v) {
    int *write = a;
    for (int *read = a; read < a + n; read++) {
        if (*read != v) {
            *write = *read;
            write++;
        }
    }
    return (int)(write - a);
}

int main(void) {
    int a[7] = {3, 7, 3, 1, 9, 3, 5};

