int count_words(const char *s) {
    int n = 0, in_word = 0;
    for (int i = 0; s[i] != '\0'; i++) {
        if (s[i] == ' ' || s[i] == '\t') {
            in_word = 0;
        } else if (!in_word) {
            in_word = 1;
            n++;
        }
    }
    return n;
}

int main(void) {
    const char *text[4] = {
        "C is a small language",
        "Pointers are the hard part",
        "Practice beats reading",
        "Write code every day",
    };

    FILE *fp = fopen("notes.txt", "w");
    if (fp == NULL) {
        printf("打不开文件\n");
        return 1;
    }
    for (int i = 0; i < 4; i++) {
        fprintf(fp, "%s\n", text[i]);
    }
    fclose(fp);

    fp = fopen("notes.txt", "r");
    if (fp == NULL) {
        printf("打不开文件\n");
        return 1;
    }

    char line[256], longest[256] = "";
    int lines = 0, words = 0;
    size_t chars = 0, best = 0;

    while (fgets(line, sizeof line, fp) != NULL) {
        line[strcspn(line, "\n")] = '\0';
        lines++;
        words += count_words(line);
        size_t len = strlen(line);
        chars += len;
        if (len > best) {
            best = len;
            snprintf(longest, sizeof longest, "%s", line);
        }
    }
    fclose(fp);

    printf("行数 %d\n", lines);
    printf("词数 %d\n", words);
    printf("字符数 %zu\n", chars);
    printf("最长的一行 %s\n", longest);

    return 0;
}

