#define CAP 100

static int buf[CAP];
static int cnt = 0;

void st_push(int v) {
    if (cnt >= CAP) return;
    buf[cnt++] = v;
}

int st_pop(void) {
    if (cnt == 0) return 0;
    return buf[--cnt];
}

int st_top(void) {
    if (cnt == 0) return 0;
    return buf[cnt - 1];
}

int st_size(void) {
    return cnt;
}

int st_empty(void) {
    return cnt == 0;
}

