#include <stdio.h>
#include <assert.h>

#define DEBUG 1

#if DEBUG
#define DBG(...) printf(__VA_ARGS__)
#else
#define DBG(...) ((void)0)
#endif

static void sort(int *a, int n) {
    for (int i = 0; i < n - 1; i++) {
        for (int j = 0; j < n - 1 - i; j++) {
            if (a[j] > a[j + 1]) {
                int t = a[j];
                a[j] = a[j + 1];
                a[j + 1] = t;
            }
        }
    }
}

static void show(const int *a, int n) {
    DBG("[调试] 排序后");
    for (int i = 0; i < n; i++) DBG(" %d", a[i]);
    DBG("\n");
}

static double median(int *a, int n) {
    assert(n > 0);
    sort(a, n);
    show(a, n);
    if (n % 2 == 1) return a[n / 2];
    return (a[n / 2 - 1] + a[n / 2]) / 2.0;
}

int main(void) {
    int a[5] = {7, 2, 9, 4, 5};
    int b[4] = {8, 3, 6, 1};

    printf("中位数 %.2f\n", median(a, 5));
    printf("中位数 %.2f\n", median(b, 4));
    return 0;
}

