#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int  id;
    char title[40];
    char author[24];
    int  borrowed;
} Book;

typedef struct {
    Book *data;
    int   n;
    int   cap;
} Shelf;

static void shelf_init(Shelf *s) {
    s->data = NULL; s->n = 0; s->cap = 0;
}

static void shelf_free(Shelf *s) {
    free(s->data);
    s->data = NULL; s->n = 0; s->cap = 0;
}

static int shelf_add(Shelf *s, Book b) {
    if (s->n == s->cap) {
        int cap = (s->cap == 0) ? 2 : s->cap * 2;
        Book *bigger = realloc(s->data, (size_t)cap * sizeof *bigger);
        if (bigger == NULL) return -1;
        s->data = bigger;
        s->cap = cap;
    }
    s->data[s->n++] = b;
    return 0;
}

static int shelf_find(const Shelf *s, const char *title) {
    for (int i = 0; i < s->n; i++) {
        if (strcmp(s->data[i].title, title) == 0) return i;
    }
    return -1;
}

static int in_stock(const Shelf *s) {
    int c = 0;
    for (int i = 0; i < s->n; i++) {
        if (!s->data[i].borrowed) c++;
    }
    return c;
}

static void borrow(Shelf *s, const char *title) {
    int k = shelf_find(s, title);
    if (k < 0) { printf("没有这本书 %s\n", title); return; }
    if (s->data[k].borrowed) { printf("已经借走了 %s\n", title); return; }
    s->data[k].borrowed = 1;
    printf("借出 %s\n", title);
}

static void give_back(Shelf *s, const char *title) {
    int k = shelf_find(s, title);
    if (k < 0) { printf("没有这本书 %s\n", title); return; }
    s->data[k].borrowed = 0;
    printf("归还 %s\n", title);
}

static int shelf_save(const Shelf *s, const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) return -1;
    for (int i = 0; i < s->n; i++) {
        const Book *b = &s->data[i];
        fprintf(fp, "%d %s %s %d\n", b->id, b->title, b->author, b->borrowed);
    }
    fclose(fp);
    return 0;
}

static int shelf_load(Shelf *s, const char *path) {
    FILE *fp = fopen(path, "r");
    if (fp == NULL) return -1;
    char line[160];
    while (fgets(line, sizeof line, fp) != NULL) {
        Book b;
        if (sscanf(line, "%d %39s %23s %d",
                   &b.id, b.title, b.author, &b.borrowed) != 4) continue;
        if (shelf_add(s, b) != 0) break;
    }
    fclose(fp);
    return 0;
}

int main(void) {
    Shelf s;
    shelf_init(&s);

    Book init[5] = {
        {1, "C程序设计", "谭浩强", 0},
        {2, "算法导论", "科尔曼", 0},
        {3, "小王子", "圣埃克苏佩里", 0},
        {4, "深入理解计算机系统", "布莱恩特", 0},
        {5, "三体", "刘慈欣", 0},
    };
    for (int i = 0; i < 5; i++) shelf_add(&s, init[i]);
    printf("共 %d 本\n", s.n);

    borrow(&s, "算法导论");
    borrow(&s, "小王子");
    printf("在馆 %d 本\n", in_stock(&s));

    give_back(&s, "小王子");
    printf("在馆 %d 本\n", in_stock(&s));

    shelf_save(&s, "library.txt");
    printf("已存入 library.txt\n");

    Shelf t;
    shelf_init(&t);
    shelf_load(&t, "library.txt");
    printf("读回 %d 本 在馆 %d 本\n", t.n, in_stock(&t));

    shelf_free(&s);
    shelf_free(&t);
    return 0;
}

